from scipy import special
from scipy.optimize import brentq


def expected_value(y):
    y = list(np.asarray(y, dtype=float).ravel())
    a = A0 + sum(y)
    b = B0 + len(y)
    def q(p):
        return brentq(lambda x: special.gammainc(a, b * x) - p, 1e-12, 1e4, xtol=1e-14, rtol=1e-14)
    p0 = float(np.exp(a * (np.log(b) - np.log(b + 1.0))))
    return [a, b, q(0.025), q(0.975), p0]
